<template>
  <main class="page" :style="themeStyle">
    <NuxtLink to="/" class="back"><Icon name="ph:arrow-left-bold"/> Voltar</NuxtLink>
    <section class="card" aria-labelledby="roulette-title">
      <span class="eyebrow">BENEFÍCIO EXCLUSIVO</span><h1 id="roulette-title">Sua sorte está lançada</h1><p>Um giro por dia. Um novo prêmio esperando por você.</p>
      <RouletteWheel :segments="segments" :rotation="rotation" :spinning="spinning"/>
      <p v-if="errorMessage" class="error" role="alert">{{ errorMessage }}</p>
      <button class="spin-button" :class="{available:canSpin&&!loading}" :disabled="loading||!canSpin||spinning" @click="spin"><Icon :name="spinning?'ph:spinner-bold':'ph:sparkle-fill'" :class="{spin:spinning}"/>{{ loading?'Preparando...':spinning?'Girando...':canSpin?'Girar agora':`Próximo giro em ${countdown}` }}</button>
    </section>
    <Teleport to="body"><div v-if="showResult" class="overlay" @click.self="closeResult"><section ref="dialog" class="dialog" role="dialog" aria-modal="true" aria-labelledby="result-title" tabindex="-1"><button class="close" aria-label="Fechar resultado" @click="closeResult"><Icon name="ph:x-bold"/></button><div class="result-icon"><Icon name="ph:confetti-bold"/></div><span class="eyebrow">RESULTADO DO DIA</span><h2 id="result-title">Parabéns!</h2><strong v-if="result?.label">{{ result.label }}</strong><p>Seu resultado foi registrado. Fale com o suporte para consultar o resgate.</p><a :href="memberExperience.supportLink" target="_blank" rel="noopener noreferrer"><Icon name="ph:whatsapp-logo-bold"/> Resgatar prêmio</a></section></div></Teleport>
  </main>
</template>
<script setup lang="ts">
import type { RouletteSegment } from '../components/RouletteWheel.vue'
definePageMeta({middleware:'auth'})
const {getAuthHeaders,isAuthenticated}=useAuth(),{memberExperience,refreshMemberExperience}=useMemberExperience()
const canSpin=ref(false),loading=ref(true),spinning=ref(false),showResult=ref(false),rotation=ref(0),errorMessage=ref(''),countdown=ref('00h00')
const result=ref<{prize:string;label:string}|null>(null),dialog=ref<HTMLElement|null>(null)
let countdownTimer:ReturnType<typeof setInterval>|null=null
const segments:RouletteSegment[]=[{key:'bonus-5',short:'R$ 5',label:'Bônus de R$ 5',color:'#9d0b62',light:'#ff4eae'},{key:'bonus-10',short:'R$ 10',label:'Bônus de R$ 10',color:'#4724a8',light:'#8e6cff'},{key:'ebook',short:'CONTEÚDO',label:'Material exclusivo',color:'#9b6810',light:'#f5c65b'},{key:'vip',short:'VIP',label:'1 dia de acesso VIP',color:'#087653',light:'#30d99d'},{key:'bonus-50',short:'R$ 50',label:'Bônus de R$ 50',color:'#a6263d',light:'#ff6c80'}]
const themeStyle=computed(()=>({'--accent':memberExperience.primaryColor||'#ff1493','--accent-soft':`color-mix(in srgb, ${memberExperience.primaryColor||'#ff1493'} 16%, transparent)`}))
const updateCountdown=()=>{const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Bahia',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).formatToParts(new Date()),v=Object.fromEntries(parts.map(p=>[p.type,p.value])),left=86400-(Number(v.hour)%24*3600+Number(v.minute)*60+Number(v.second));countdown.value=`${String(Math.floor(left/3600)).padStart(2,'0')}h${String(Math.floor(left%3600/60)).padStart(2,'0')}`}
const loadStatus=async()=>{loading.value=true;if(!isAuthenticated.value){errorMessage.value='Entre na sua conta para usar o giro diário.';canSpin.value=false;loading.value=false;return}try{const data=await $fetch<any>('/api/roulette/status',{headers:getAuthHeaders()});canSpin.value=data.canSpin;result.value=data.spin;updateCountdown()}catch(e:any){errorMessage.value=e?.data?.message||'Não foi possível consultar sua participação.'}finally{loading.value=false}}
const spin=async()=>{if(!canSpin.value||spinning.value)return;spinning.value=true;errorMessage.value='';try{const data=await $fetch<{prize:string;label:string}>('/api/roulette/spin',{method:'POST',headers:getAuthHeaders()}),index=Math.max(0,segments.findIndex(item=>item.key===data.prize));rotation.value+=1800-index*(360/segments.length)-360/segments.length/2;await new Promise(r=>setTimeout(r,4000));result.value=data;canSpin.value=false;showResult.value=true;await nextTick();dialog.value?.focus()}catch(e:any){errorMessage.value=e?.data?.message||e?.message||'Não foi possível realizar o giro.';await loadStatus()}finally{spinning.value=false}}
const closeResult=()=>showResult.value=false
const onKey=(e:KeyboardEvent)=>{if(e.key==='Escape'&&showResult.value)closeResult()}
watch(showResult,open=>document.body.style.overflow=open?'hidden':'')
onMounted(async()=>{await Promise.all([refreshMemberExperience(),loadStatus()]);countdownTimer=setInterval(updateCountdown,30000);window.addEventListener('keydown',onKey)})
onUnmounted(()=>{if(countdownTimer)clearInterval(countdownTimer);window.removeEventListener('keydown',onKey);document.body.style.overflow=''})
useHead({title:'Roleta diária'})
</script>
<style scoped>
.page{--accent:#ff1493;--accent-soft:#ff149329;min-height:100vh;padding:76px 18px 42px;display:grid;place-items:center;overflow-x:clip;color:#f8f6fa;background:radial-gradient(circle at 50% 8%,var(--accent-soft),transparent 32%),linear-gradient(160deg,#09090d,#050507);font-family:Manrope,sans-serif}.back{position:absolute;top:20px;left:max(12px,calc((100vw - 980px)/2));min-height:44px;padding:0 12px;color:#d0cbd1;text-decoration:none;display:flex;gap:8px;align-items:center;border-radius:12px;transition:.18s}.back:hover,.back:focus-visible{color:#fff;background:#ffffff0b;outline:2px solid var(--accent)}.card{width:min(100%,620px);padding:44px 32px 36px;text-align:center;border:1px solid #ffffff18;border-radius:26px;background:color-mix(in srgb,#16151d 82%,transparent);box-shadow:0 35px 100px #000b;backdrop-filter:blur(22px)}.eyebrow{color:color-mix(in srgb,var(--accent) 65%,white);font-size:11px;font-weight:900;letter-spacing:.14em}.card h1{margin:9px 0 8px;font-size:clamp(32px,7vw,52px);line-height:1.05;letter-spacing:-.045em}.card>p{color:#b7b3bc;line-height:1.6}.spin-button{min-height:52px;display:inline-flex;align-items:center;justify-content:center;gap:9px;padding:0 24px;border:1px solid color-mix(in srgb,var(--accent) 55%,white);border-radius:14px;background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 88%,white),var(--accent));color:#170511;font:inherit;font-weight:900;cursor:pointer;box-shadow:0 12px 30px var(--accent-soft);transition:.18s}.spin-button:hover:not(:disabled){transform:translateY(-2px)}.spin-button:focus-visible{outline:3px solid #fff;outline-offset:3px}.spin-button:disabled{opacity:.68}.spin-button.available{animation:pulse 2.2s ease-in-out infinite}.spin{animation:turn .7s linear infinite}.error{margin:0 0 18px;color:#ff8796}.overlay{position:fixed;inset:0;z-index:11000;display:grid;place-items:center;padding:20px;background:#020204cc;backdrop-filter:blur(16px)}.dialog{position:relative;width:min(100%,430px);padding:42px 30px;text-align:center;color:#fff;border:1px solid #ffffff20;border-radius:24px;background:radial-gradient(circle at 50% 0,var(--accent-soft),transparent 46%),#121118;box-shadow:0 40px 100px #000;animation:enter .45s cubic-bezier(.16,1,.3,1)}.dialog:focus{outline:none}.result-icon{width:70px;height:70px;margin:0 auto 18px;display:grid;place-items:center;border-radius:22px;color:var(--accent);font-size:38px;background:var(--accent-soft)}.dialog h2{margin:8px 0;font-size:35px}.dialog>strong{display:block;color:color-mix(in srgb,var(--accent) 65%,white);font-size:25px}.dialog p{margin:13px 0 24px;color:#b6b2ba;line-height:1.55}.dialog>a{min-height:48px;display:inline-flex;align-items:center;gap:8px;padding:0 20px;border-radius:13px;background:var(--accent);color:#16040f;font-weight:900;text-decoration:none}.close{position:absolute;top:12px;right:12px;width:44px;height:44px;border:0;border-radius:50%;color:#ddd;background:#ffffff09;cursor:pointer}.close:focus-visible,.dialog>a:focus-visible{outline:3px solid #fff;outline-offset:3px}@keyframes pulse{50%{box-shadow:0 12px 38px color-mix(in srgb,var(--accent) 45%,transparent)}}@keyframes turn{to{transform:rotate(1turn)}}@keyframes enter{from{opacity:0;transform:translateY(20px) scale(.96)}}@media(max-width:480px){.card{padding:34px 12px 28px;border-radius:22px}.page{padding-inline:10px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important}}
</style>
